from collections import Counter, deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        q.append((a, b))
            result.append((color, cells))
    return result


def _corner(cells):
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    points = set(cells)
    shapes = {
        "tl": {(r0, c) for c in range(c0, c1 + 1)} | {(r, c0) for r in range(r0, r1 + 1)},
        "tr": {(r0, c) for c in range(c0, c1 + 1)} | {(r, c1) for r in range(r0, r1 + 1)},
        "bl": {(r1, c) for c in range(c0, c1 + 1)} | {(r, c0) for r in range(r0, r1 + 1)},
        "br": {(r1, c) for c in range(c0, c1 + 1)} | {(r, c1) for r in range(r0, r1 + 1)},
    }
    if r0 < r1 and c0 < c1:
        for k, shape in shapes.items():
            if points == shape:
                return k, (r0, r1, c0, c1)
    return None


def transform(grid):
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    comps = _components(grid)
    markers = [(color, cells, _corner(cells)) for color, cells in comps
               if color != background and _corner(cells) is not None]
    if not markers:
        return out
    marker_color, marker_cells, shape = max(markers, key=lambda x: len(x[1]))
    if shape is None:
        return out
    orient, (r0, r1, c0, c1) = shape
    # Select the largest substantial object fully in the open southeast sector.
    if orient == "br":
        candidates = []
        for color, cells in comps:
            if color in (background, marker_color, 0) or len(cells) < 3 or _corner(cells):
                continue
            if all(r > r1 and c > c1 for r, c in cells):
                candidates.append(cells)
        if candidates:
            target = max(candidates, key=len)
            for r, c in target:
                out[r][c] = marker_color
    elif orient == "bl":
        candidates = []
        for color, cells in comps:
            if color in (background, marker_color, 0) or len(cells) < 3 or _corner(cells):
                continue
            if all(r >= r1 and c >= c1 for r, c in cells):
                candidates.append(cells)
        if candidates:
            target = max(candidates, key=len)
            for r, c in target:
                out[r][c] = marker_color
    return out


